use proc_macro::TokenStream;
use proc_macro2::TokenStream as TokenStream2;
use quote::quote;
use syn::{parse_macro_input, Data, DeriveInput, Fields};

/// Derives an associated `FIELD_NAMES` constant listing every field of the type.
///
/// Internally the compiler's `proc_macro::TokenStream` is bridged to
/// `proc_macro2::TokenStream`, so the token-processing pipeline is a stable,
/// ordinary Rust API that can also be exercised outside the compiler.
#[proc_macro_derive(FieldNames)]
pub fn field_names(input: TokenStream) -> TokenStream {
    let input = parse_macro_input!(input as DeriveInput);
    let ident = &input.ident;

    let fields: Vec<String> = match &input.data {
        Data::Struct(data) => match &data.fields {
            Fields::Named(named) => named
                .named
                .iter()
                .filter_map(|field| field.ident.as_ref())
                .map(ToString::to_string)
                .collect(),
            Fields::Unnamed(unnamed) => {
                (0..unnamed.unnamed.len()).map(|i| i.to_string()).collect()
            }
            Fields::Unit => Vec::new(),
        },
        Data::Enum(_) | Data::Union(_) => Vec::new(),
    };

    let expanded: TokenStream2 = quote! {
        impl #ident {
            pub const FIELD_NAMES: &'static [&'static str] = &[#(#fields),*];
        }
    };

    expanded.into()
}

#[cfg(test)]
mod tests {
    use super::*;
    use syn::parse_quote;

    #[test]
    fn derives_field_names_from_a_struct() {
        let input: DeriveInput = parse_quote! {
            struct Point {
                x: i32,
                y: i32,
            }
        };

        let output = field_names_impl(input);
        let rendered = output.to_string();
        assert!(rendered.contains("\"x\""));
        assert!(rendered.contains("\"y\""));
    }

    fn field_names_impl(input: DeriveInput) -> TokenStream2 {
        let ident = &input.ident;
        let fields: Vec<String> = match &input.data {
            Data::Struct(data) => match &data.fields {
                Fields::Named(named) => named
                    .named
                    .iter()
                    .filter_map(|field| field.ident.as_ref())
                    .map(ToString::to_string)
                    .collect(),
                Fields::Unnamed(unnamed) => {
                    (0..unnamed.unnamed.len()).map(|i| i.to_string()).collect()
                }
                Fields::Unit => Vec::new(),
            },
            Data::Enum(_) | Data::Union(_) => Vec::new(),
        };

        quote! {
            impl #ident {
                pub const FIELD_NAMES: &'static [&'static str] = &[#(#fields),*];
            }
        }
    }
}

